pub assume_specification<T: Copy, E>[ Result::<&T, E>::copied ](
    result: Result<&T, E>,
) -> (res: Result<T, E>)
    ensures
        res == match result {
            Result::Ok(value) => Result::Ok(*value),
            Result::Err(error) => Result::Err(error),
        },
;
